import * as THREE from 'three';
import {createRig} from './rig.mjs';
import {presets} from './parameters.mjs';
const canvas=document.querySelector('#view'), renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true,preserveDrawingBuffer:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color('#f6efe3');
const camera=new THREE.PerspectiveCamera(34,1,.1,100);scene.add(new THREE.HemisphereLight(0xfff6e8,0x8d6e55,2.1));const key=new THREE.DirectionalLight(0xffedd7,3);key.position.set(-3,7,6);scene.add(key);const fill=new THREE.DirectionalLight(0xffffff,1.2);fill.position.set(4,3,-4);scene.add(fill);
const floor=new THREE.Mesh(new THREE.CircleGeometry(2.6,64),new THREE.MeshStandardMaterial({color:0xe7d8c5,roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.025;scene.add(floor);
let weights={M:34,W:33,B:33},rig=createRig(scene,weights),pose='neutral',progress=0,paused=true,view='threequarter',rafHandle=null;
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches, pause=document.querySelector('#pause');if(reduce){pause.disabled=true;pause.textContent='Reduced motion';}
const positions={front:[0,1.76,8.2],threequarter:[5.1,1.96,6.4]};
function setCamera(){const a=canvas.clientWidth/canvas.clientHeight;camera.aspect=a;camera.position.set(...positions[view]);camera.lookAt(0,1.76,0);camera.updateProjectionMatrix();}
function paint(){setCamera();renderer.setSize(canvas.clientWidth,canvas.clientHeight,false);renderer.render(scene,camera);}
new ResizeObserver(paint).observe(canvas);paint();document.querySelector('#loading').hidden=true;
function renderRecipe(){rig.dispose();rig=createRig(scene,weights);rig.setPose(pose,progress);document.querySelector('#caption').textContent=`Custom mixture · ${weights.M} / ${weights.W} / ${weights.B}`;document.querySelector('#readout').textContent=`Geometry: hood ${rig.parameters.hoodWidth.toFixed(2)} × ${rig.parameters.hoodHeight.toFixed(2)} · face ${rig.parameters.faceWindowRatio.toFixed(2)}`;paint();}
const labels={M:'Mars Mission',W:'Wobbly Life',B:'Bot Crossing'},sliders=document.querySelector('#sliders');
for(const k of ['M','W','B']){const box=document.createElement('div');box.className='slider';box.innerHTML=`<label for="weight-${k}">${labels[k]} <output>${weights[k]}%</output></label><input id="weight-${k}" type="range" min="0" max="100" value="${weights[k]}">`;const input=box.querySelector('input');input.addEventListener('input',()=>{const v=Number(input.value),other=['M','W','B'].filter(x=>x!==k),remaining=100-v,old=weights[other[0]]+weights[other[1]];weights[k]=v;weights[other[0]]=old?Math.round(remaining*weights[other[0]]/old):Math.floor(remaining/2);weights[other[1]]=remaining-weights[other[0]];for(const [idx,key] of ['M','W','B'].entries()){const el=sliders.children[idx];el.querySelector('input').value=weights[key];el.querySelector('output').value=`${weights[key]}%`;}document.querySelectorAll('.presets button').forEach(b=>b.classList.remove('active'));renderRecipe();});sliders.append(box);}
const presetBox=document.querySelector('#presets');for(const p of presets){const b=document.createElement('button');b.textContent=`${p.name} · ${p.weights.M}/${p.weights.W}/${p.weights.B}`;b.addEventListener('click',()=>{weights={...p.weights};[...sliders.children].forEach((el,i)=>{const k=['M','W','B'][i];el.querySelector('input').value=weights[k];el.querySelector('output').value=`${weights[k]}%`;});document.querySelectorAll('.presets button').forEach(x=>x.classList.toggle('active',x===b));renderRecipe();});presetBox.append(b);}
document.querySelectorAll('[data-pose]').forEach(b=>b.onclick=()=>{pose=b.dataset.pose;progress=pose==='neutral'?0:pose==='reach'?1:.5;rig.setPose(pose,progress);document.querySelectorAll('[data-pose]').forEach(x=>x.classList.toggle('active',x===b));paint();});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));paint();});
pause.onclick=()=>{if(reduce)return;paused=!paused;pause.textContent=paused?'Paused':'Playing';pause.setAttribute('aria-pressed',String(paused));if(paused){if(rafHandle!==null)cancelAnimationFrame(rafHandle);rafHandle=null;}else{pose='hop';progress=0;rig.setPose(pose,progress);document.querySelectorAll('[data-pose]').forEach(b=>b.classList.toggle('active',b.dataset.pose===pose));paint();scheduleTick();}};
document.querySelector('#export').onclick=()=>{const prior={...weights},oldPose=pose,oldProgress=progress,oldView=view;const out=document.createElement('canvas'),ctx=out.getContext('2d'),cellW=760,cellH=540;out.width=cellW*2;out.height=cellH*4;ctx.fillStyle='#f6efe3';ctx.fillRect(0,0,out.width,out.height);for(let i=0;i<presets.length;i++){weights={...presets[i].weights};rig.dispose();rig=createRig(scene,weights);rig.setPose('neutral',0);view='front';paint();const x=(i%2)*cellW,y=Math.floor(i/2)*cellH;ctx.drawImage(canvas,x,y,cellW,cellH-38);ctx.fillStyle='#382a23';ctx.font='700 19px system-ui';ctx.fillText(`${presets[i].name} · M${weights.M}/W${weights.W}/B${weights.B}`,x+18,y+cellH-13);}weights=prior;pose=oldPose;progress=oldProgress;view=oldView;rig.dispose();rig=createRig(scene,weights);rig.setPose(pose,progress);paint();const a=document.createElement('a');a.download='iteration-14-procedural-mix-recipes.png';a.href=out.toDataURL('image/png');a.click();};
function scheduleTick(){if(!paused&&rafHandle===null)rafHandle=requestAnimationFrame(tick);}
function tick(now){rafHandle=null;if(paused)return;progress=(now%2400)/2400;rig.setPose(pose,progress);paint();scheduleTick();}
window.__mix={getState:()=>({weights,pose,progress,view,paused,rafPending:rafHandle!==null,parameters:rig.parameters,geometryCount:rig.geometryCount}),setRecipe:w=>{weights={...w};renderRecipe();},paint};
renderRecipe();
